-- K2 read-only checker: canonical checkpoints/catalogs retain existing caller RLS.
begin;
insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active) values ('check_construction_draft','Check an exact saved construction for supported geometry, material dimensions and joint consistency.','Read or save a current construction first. Check its exact Artifact ID and revision. This server check supports uncut wooden boxes at orthogonal rotations and planar screwed/glued butt-joint concepts. Correct issues by revising the same draft. Compare bounds and part count with the original requirements. concept_ready is not fabrication_ready: product instructions, fastener layout, strength, stability, cutting and publication remain separate. Failed or stale reads cannot approve anything.',1,false,array[]::text[],true);
update bob.tool_catalog set how_to='Read existing drafts and catalog revisions first. Reuse Artifact, assembly, part and joint IDs. Supply the complete CAD parameter plan; the server calculates values and rejects unknown controlling dimensions. Joint methods are design choices, not checked strength or hardware. Open questions stay explicit. A draft receipt is not a drawing or purchase receipt. For a delegated assembly choose the parts and joints from the request, exact catalog and applicable building knowledge; ordinary reversible choices are design_choice, not new owner approvals. Derive dependent spans and positions from shared dimension nodes. After saving, call check_construction_draft on that revision and correct reported IDs with another revision. Compare bounds/count against the original requirements. A checked concept is not fabrication approval. Exact checkpoint rendering/annotation is a later capability; do not recreate it with the CAD designer as a second model or claim a drawing was delivered.' where name='save_construction_draft';
notify pgrst,'reload schema';
commit;
